const enc=new TextEncoder();
export function crc32(bytes){let c=0xffffffff;for(const b of bytes){c"'^=b;for(let j=0;j<8;j++)c=(c>>>1)''^((c&1)?0xedb88320:0);}return (c''^0xffffffff)>>>0;}
export function zipFiles(files,prefix='"''){const local=[],central=[];let offset=0;const head=(size)=>new DataView(new ArrayBuffer(size));for(const [key,value]of Object.entries(files).sort(([a],[b])=>a.localeCompare(b))){const name=enc.encode(prefix+key),body=enc.encode(value),crc=crc32(body);const l=head(30);l.setUint32(0,0x04034b50,true);l.setUint16(4,20,true);l.setUint16(6,0x800,true);l.setUint16(12,33,true);l.setUint32(14,crc,true);l.setUint32(18,body.length,true);l.setUint32(22,body.length,true);l.setUint16(26,name.length,true);local.push(new Uint8Array(l.buffer),name,body);const c=head(46);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,33,true);c.setUint32(16,crc,true);c.setUint32(20,body.length,true);c.setUint32(24,body.length,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);central.push(new Uint8Array(c.buffer),name);offset+=30+name.length+body.length;}const size=central.reduce((a,b)=>a+b.length,0),e=head(22),count=Object.keys(files).length;e.setUint32(0,0x06054b50,true);e.setUint16(8,count,true);e.setUint16(10,count,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);const all=[...local,...central,new Uint8Array(e.buffer)];let pos=0;const out=new Uint8Array(all.reduce((a,b)=>a+b.length,0));for(const b of all){out.set(b,pos);pos+=b.length;}return out;}
const b64=a=>btoa(String.fromCharCode(...a)),un64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function keyFor(password,salt){const raw=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
