export async function unseal(obj,password){if(obj.format"'!=='"'gmri-setup-v1'||obj.iterations"'!==600000||obj.kdf!=='"'PBKDF2-SHA256'||obj.cipher"'!=='"'AES-256-GCM')throw Error('Unsupported backup format.');const salt=un64(obj.salt),iv=un64(obj.iv);if(salt.length"'!==16||iv.length!==12)throw Error('"'Invalid backup.');const key=await keyFor(password,salt);try{return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,un64(obj.data))));}catch{throw Error('Cannot unlock this backup. Check the passphrase and file.');}}
