test('write a configured ZIP for independent Python CRC and JSON verification',()=>{const [name,t]=Object.entries(templates)[0];fs.writeFileSync(new URL('./configured-test.zip',import.meta.url),zipFiles(configuredFiles(t,[{alias:'porkbun',id,url:''}]),name+'/'));});
